let region;const notices=new Map();
export function dismissNotice(id){notices.get(id)?.remove();}
export function notify(text,{type='info',id,duration}={}){if(!String(text||'').trim())return;if(!region){region=document.createElement('section');region.className='admin-notices';region.setAttribute('aria-label','Avisos del administrador');document.body.append(region);}const key=id||type+':'+text;let record=notices.get(key);if(record&&record.text===text)return;if(!record){const toast=document.createElement('div'),icon=document.createElement('span'),body=document.createElement('p'),close=document.createElement('button');toast.className='admin-toast';icon.className='toast-symbol';icon.setAttribute('aria-hidden','true');close.type='button';close.className='toast-close';close.textContent='×';close.setAttribute('aria-label','Cerrar aviso');const remove=()=>{clearTimeout(record.timer);toast.remove();notices.delete(key);};close.onclick=remove;toast.append(icon,body,close);region.append(toast);record={toast,icon,body,remove,text:'',timer:null};notices.set(key,record);toast.addEventListener('mouseenter',()=>clearTimeout(record.timer));toast.addEventListener('focusin',()=>clearTimeout(record.timer));while(notices.size>4){const first=notices.values().next().value;if(first===record)break;first.remove();}}
 record.text=text;record.toast.dataset.type=type;record.toast.setAttribute('role',type==='error'?'alert':'status');record.icon.textContent={error:'!',warning:'!',success:'✓',info:'i'}[type]||'i';record.body.textContent=text;clearTimeout(record.timer);const timeout=duration??(type==='error'?0:type==='warning'?12000:6500);if(timeout)record.timer=setTimeout(record.remove,timeout);
}
export function watchAdminNotices(){const status=document.querySelector('#status');if(status){status.classList.add('admin-status-hidden');status.removeAttribute('role');}let warningTimer;const errors=document.querySelector('#spec-errors');if(errors)new MutationObserver(()=>{clearTimeout(warningTimer);const text=errors.textContent.trim();if(!text)notices.get('compatibility')?.remove();if(text)warningTimer=setTimeout(()=>notify(text,{type:'warning',id:'compatibility'}),600);}).observe(errors,{childList:true,characterData:true,subtree:true});const catalog=document.querySelector('#spec-status');if(catalog)new MutationObserver(()=>{const text=catalog.textContent.trim();if(/no se pudo|no respondió|no devolvió|no se encontró|no hay|no confirma|temporalmente no disponible|reintentar/i.test(text))notify(text,{type:'warning',id:'catalog-warning'});}).observe(catalog,{childList:true,characterData:true,subtree:true});const research=document.querySelector('#research-status');if(research)new MutationObserver(()=>{const text=research.textContent.trim();if(text)notify(text,{type:/buscando|consultando/i.test(text)?'info':/error|no hay|no se|confianza baja/i.test(text)?'warning':'success',id:'research',duration:/buscando|consultando/i.test(text)?0:10000});}).observe(research,{childList:true,characterData:true,subtree:true});}
